use rayon::prelude::*;use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{alloc::{GlobalAlloc,Layout,System},sync::{Arc,Mutex,atomic::{AtomicUsize,Ordering::Relaxed}},time::Instant};use zopro_bn254::{Fp,FpConfig,FqConfig,FrConfig,ifma8::Ifma8};mod perf;
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/blocked-pair52-native176/bench";
static ALLOCS:AtomicUsize=AtomicUsize::new(0);struct Counted;unsafe impl GlobalAlloc for Counted{unsafe fn alloc(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{System.alloc(l)}}unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{System.alloc_zeroed(l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{System.realloc(p,l,n)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}}#[global_allocator]static A:Counted=Counted;
fn canonical<C:FpConfig>(mut w:[u64;4])->Fp<C>{loop{if let Some(v)=Fp::from_canonical(w){return v;}let mut borrow=0u128;for i in 0..4{let t=(1u128<<64)+w[i]as u128-C::P[i]as u128-borrow;w[i]=t as u64;borrow=1-(t>>64);}assert_eq!(borrow,0);}}
fn seed<C:FpConfig>(field:&str,op:&str,worker:usize,bank:usize,slot:usize,lane:usize)->Fp<C>{let mut h=Sha256::new();h.update(b"deferred-limb-sign176/changing-v1");h.update(field.as_bytes());h.update(op.as_bytes());for i in[worker,bank,slot,lane]{h.update((i as u64).to_le_bytes());}let bytes=h.finalize();canonical(std::array::from_fn(|i|u64::from_le_bytes(bytes[i*8..i*8+8].try_into().unwrap())))}
#[inline(never)]fn loop_kernel<C:FpConfig,const M:bool,const OP:usize>(banks:&mut[[Ifma8<C,M>;4]],rounds:usize){for _ in 0..rounds{for bank in banks.iter_mut(){let[a,b,c,d]=*bank;
 #[cfg(bench_new)]let value=match OP{0=>a.blocked_mul(&b),1=>a.blocked_sum2(&b,&c,&d),2=>a.blocked_difference2(&b,&c,&d),_=>unreachable!()};
 #[cfg(bench_old)]let value=match OP{0=>a.control_mul(&b),1=>a.control_sum2(&b,&c,&d),2=>a.control_difference2(&b,&c,&d),_=>unreachable!()};
 #[cfg(not(any(bench_new,bench_old)))]let value=match OP{0=>a.mul(&b),1=>a.sum2(&b,&c,&d),2=>a.difference2(&b,&c,&d),_=>unreachable!()};
 *bank=[b,c,d,value];}}}
struct Fixture<C:FpConfig,const M:bool>{initial:Vec<[Ifma8<C,M>;4]>,banks:Vec<[Ifma8<C,M>;4]>}
impl<C:FpConfig,const M:bool> Fixture<C,M>{fn new(case:&str,worker:usize,s:usize)->Self{let op=case.split('_').nth(1).unwrap();let initial=(0..s).map(|b|std::array::from_fn(|slot|Ifma8::new(&std::array::from_fn(|lane|seed::<C>(&case[..2],op,worker,b,slot,lane))))).collect::<Vec<_>>();Self{banks:initial.clone(),initial}}fn reset(&mut self){self.banks.copy_from_slice(&self.initial);}fn capacity(&self)->[usize;2]{[self.initial.capacity()*std::mem::size_of::<[Ifma8<C,M>;4]>(),self.banks.capacity()*std::mem::size_of::<[Ifma8<C,M>;4]>()]}fn digest(&self,h:&mut Sha256){for b in &self.banks{for v in b{for p in v.get(){for w in p.to_canonical(){h.update(w.to_le_bytes());}}}}}}
fn affinity(cpu:usize){unsafe{let mut m:libc::cpu_set_t=std::mem::zeroed();libc::CPU_ZERO(&mut m);libc::CPU_SET(cpu,&mut m);assert_eq!(libc::sched_setaffinity(0,std::mem::size_of_val(&m),&m),0);}}
fn run<C:FpConfig,const M:bool,const OP:usize>(case:&str,workers:usize,rounds:usize,arm:&str,s:usize){let gold:Value=serde_json::from_slice(&std::fs::read(format!("{ROOT}/gold.json")).unwrap()).unwrap();let expected=|n:usize|gold["rows"][format!("{case}-w{workers}-r{n}")]["output_sha256"].as_str().unwrap();let seen=Arc::new(Mutex::new(vec![]));let sc=seen.clone();let pool=rayon::ThreadPoolBuilder::new().num_threads(workers).stack_size(512*1024).start_handler(move|i|{let cpu=if workers==1{2}else{i};affinity(cpu);sc.lock().unwrap().push(json!({"worker":i,"cpu":cpu,"tid":unsafe{libc::syscall(libc::SYS_gettid)}}));}).build().unwrap();pool.broadcast(|_|());let mut mapping=seen.lock().unwrap().clone();mapping.sort_by_key(|v|v["worker"].as_u64().unwrap());let mut fixtures=(0..workers).map(|w|Fixture::<C,M>::new(case,w,s)).collect::<Vec<_>>();let digest=|f:&Vec<Fixture<C,M>>|{let mut h=Sha256::new();for f in f{f.digest(&mut h);}format!("{:x}",h.finalize())};for _ in 0..3{for f in &mut fixtures{f.reset();}pool.install(||fixtures.par_iter_mut().for_each(|f|loop_kernel::<C,M,OP>(&mut f.banks,128)));assert_eq!(digest(&fixtures),expected(128));}for f in &mut fixtures{f.reset();}let caps=fixtures.iter().map(Fixture::capacity).collect::<Vec<_>>();let mut ctl=perf::Control::from_env().unwrap();if let Some(c)=ctl.as_mut(){c.enable().unwrap();}let u0=perf::Usage::now().unwrap();let a0=ALLOCS.load(Relaxed);let t=Instant::now();pool.install(||fixtures.par_iter_mut().for_each(|f|loop_kernel::<C,M,OP>(std::hint::black_box(&mut f.banks),std::hint::black_box(rounds))));let ns=t.elapsed().as_nanos()as u64;let allocs=ALLOCS.load(Relaxed)-a0;let u1=perf::Usage::now().unwrap();if let Some(c)=ctl.as_mut(){c.disable().unwrap();}assert_eq!(allocs,0);let out=digest(&fixtures);assert_eq!(out,expected(rounds));assert_eq!(caps,fixtures.iter().map(Fixture::capacity).collect::<Vec<_>>());pool.broadcast(|ctx|assert_eq!(unsafe{libc::sched_getcpu()},if workers==1{2}else{ctx.index()}as i32));println!("CALLER {}",json!({"case":case,"workers":workers,"rounds_per_worker":rounds,"arm":arm,"streams":s,"elapsed_ns":ns,"ns_per_wave":ns as f64/rounds as f64,"pid":std::process::id(),"worker_rows":mapping,"capacity_bytes_by_worker":caps,"timed_allocations":allocs,"output_sha256":out,"independent_gold":true,"priming_passes":3,"priming_rounds":128,"usage":u1.difference(&u0),"new_proofs":0}));}
fn main(){let a=std::env::args().collect::<Vec<_>>();assert_eq!(a.len(),5);let case=&a[1];let w=a[2].parse().unwrap();assert!([1,16,32].contains(&w));let r=a[3].parse().unwrap();let arm=&a[4];assert_eq!(cfg!(bench_new),arm=="ON");assert_eq!(cfg!(bench_old),arm=="OLD");assert!(["accepted","OFF","OLD","ON"].contains(&arm.as_str()));let (s,op)=match case.split('_').nth(1).unwrap(){"mul1"=>(1,0),"mul4"=>(4,0),"sum1"=>(1,1),"diff1"=>(1,2),_=>panic!("op")};macro_rules! go{($c:ty,$m:literal)=>{match op{0=>run::<$c,$m,0>(case,w,r,arm,s),1=>run::<$c,$m,1>(case,w,r,arm,s),2=>run::<$c,$m,2>(case,w,r,arm,s),_=>unreachable!()}};}match &case[..5]{"fq256"=>go!(FqConfig,true),"fr256"=>go!(FrConfig,true),"fq260"=>go!(FqConfig,false),"fr260"=>go!(FrConfig,false),_=>panic!("field/radix")}}
